<div class="patient-page-heading"><div><span class="eyebrow text-secondary"><?= $escape($doctor['codigo_medico']) ?></span><h1><?= $escape($doctor['nombres'].' '.$doctor['apellidos']) ?></h1><span class="status-chip <?= $doctor['estado']==='activo' ? 'is-active' : 'is-inactive' ?>"><?= $escape(ucfirst($doctor['estado'])) ?></span></div><a class="btn btn-clinic" href="/medicos/editar?id=<?= $escape($doctor['id_medico']) ?>">Editar médico y especialidades</a></div>
<section class="patient-card patient-detail-section"><h2 class="h5">Información profesional</h2><dl class="row mb-0"><?php foreach(['codigo_medico'=>'Código de médico','registro_profesional'=>'Registro profesional','nombres'=>'Nombres','apellidos'=>'Apellidos','telefono'=>'Teléfono','correo_contacto'=>'Correo de contacto','cuenta_usuario'=>'Cuenta web vinculada'] as $field=>$label): ?><div class="col-md-6 mb-3"><dt><?= $escape($label) ?></dt><dd><?= $escape($doctor[$field] ?: 'Sin registrar') ?></dd></div><?php endforeach; ?></dl></section>
<section class="patient-card patient-detail-section"><h2 class="h5">Especialidades asociadas</h2><?php if(!$doctor['especialidades']): ?><p class="mb-0">Sin especialidades asociadas.</p><?php else: ?><ul class="medical-association-list"><?php foreach($doctor['especialidades'] as $e): ?><li><div><strong><?= $escape($e['nombre']) ?></strong><small><?= $escape(ucfirst($e['estado'])) ?> · Bs <?= $escape($e['precio_consulta']) ?> por consulta</small></div><?php if((int)$e['tiene_citas']===1): ?><span class="text-secondary small">Vinculada a citas; debe conservarse.</span><?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?></section><a class="back-link text-start mt-4" href="/medicos">← Volver a médicos</a>
